with OrderStats as (select order_id, avg(unit_price) as avg_unit_price, max(unit_price) - min(unit_price) as unit_price_range from order_items group by order_id) select orders.id, orders.channel, OrderStats.avg_unit_price, OrderStats.unit_price_range from orders join OrderStats on orders.id = OrderStats.order_id where OrderStats.avg_unit_price > 180 order by OrderStats.unit_price_range asc, id asc limit 1
